package com.bank.secrets;

import java.util.*;
import java.util.logging.Logger;

// Vault-like store: issues short-lived secrets by name and AUDITS every access.
public class SecretStore {
    private static final Logger log = Logger.getLogger(SecretStore.class.getName());
    private final Map<String, String> backing = new HashMap<>();
    private final List<String> auditLog = new ArrayList<>();

    public void put(String name, String value) { backing.put(name, value); }

    // Issue a short-lived copy and record who/what accessed it.
    public Secret issue(String name, String caller) {
        String v = backing.get(name);
        if (v == null) throw new NoSuchElementException("No secret: " + name);
        auditLog.add(caller + " read '" + name + "' at " + java.time.Instant.now());
        log.info(() -> "SecretStore issued short-lived '" + name + "' to " + caller);
        return new Secret(v, 300); // 5-minute TTL
    }

    public List<String> auditLog() { return List.copyOf(auditLog); }
}
