package com.bank.secrets;

import java.util.logging.Logger;

// Masks secret values so they never appear in plain text in logs.
public class MaskingLogger {
    private static final Logger log = Logger.getLogger(MaskingLogger.class.getName());

    public void info(String message, Secret secret) {
        // Replace the actual value with *** before logging.
        String masked = message.replace(secret.value(), "***");
        log.info(masked);
    }
}
