package com.bank.secrets;

// A deploy step that fetches secrets at runtime and uses them masked.
public class PipelineStep {
    private final SecretStore store;
    private final MaskingLogger maskLog = new MaskingLogger();

    public PipelineStep(SecretStore store) { this.store = store; }

    public void deploy() {
        // Fetch at the moment of use, scoped to this step only.
        Secret dbPassword     = store.issue("prod/db-password", "deploy-step");
        Secret registryToken  = store.issue("prod/registry-token", "deploy-step");

        // Use them, but logs are masked.
        maskLog.info("docker login registry.bank.local -p " + registryToken.value(), registryToken);
        maskLog.info("kubectl create secret db --from-literal=pass=" + dbPassword.value(), dbPassword);
        // Secrets go out of scope here; nothing is persisted.
    }
}
