package com.bank.secrets;

import java.util.List;

// Refuses to bake any secret-looking value into an image layer.
public class ImageBuilder {
    public void build(List<String> dockerfileLines) {
        for (String line : dockerfileLines) {
            String upper = line.toUpperCase();
            if (upper.startsWith("ENV") &&
                    (upper.contains("PASSWORD") || upper.contains("SECRET")
                            || upper.contains("KEY") || upper.contains("TOKEN"))) {
                throw new SecurityException("Refusing to bake secret into image: " + line);
            }
        }
        System.out.println("Image built with code only; secrets injected at runtime.");
    }
}
