package com.bank.secrets;

import java.util.List;
import java.util.logging.*;

public class SecretsDemo {
    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new SecretsLogFormatter());
        root.addHandler(ch);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        Logger log = Logger.getLogger(SecretsDemo.class.getName());

        SecretStore store = new SecretStore();
        store.put("prod/db-password", "S3cr3t-DB-Pass!");
        store.put("prod/registry-token", "ghp_tokenABC123");

        log.info("=== Deploy step fetches masked secrets at runtime ===");
        new PipelineStep(store).deploy();

        log.info("=== Secret store audit log ===");
        store.auditLog().forEach(log::info);

        log.info("=== Image builder rejects baked-in secrets ===");
        try {
            new ImageBuilder().build(List.of(
                    "FROM eclipse-temurin:21-jre",
                    "COPY app.jar /app.jar",
                    "ENV DB_PASSWORD=S3cr3t-DB-Pass!"));   // should be rejected
        } catch (SecurityException e) {
            log.severe(e.getMessage());
        }

        new ImageBuilder().build(List.of(
                "FROM eclipse-temurin:21-jre",
                "COPY app.jar /app.jar"));   // clean image, secrets at runtime
    }
}

// ─── Would be in SecretsLogFormatter.java in a real project ───
class SecretsLogFormatter extends Formatter {
    @Override public String format(LogRecord r) {
        return String.format("%1$tF %1$tT [%2$s] %3$s%n",
                new java.util.Date(r.getMillis()), r.getLevel(), r.getMessage());
    }
}
